head.script:
scwin.onpageload = function() {
	grid1.setData(["가", 5, "서울", 12,
		"나", 4, "인천", 34,
		"다", 8, "대구", 64,
		"라", 1, "부산", 23
	]);
};

scwin.checkVal = function() {
	const checked1 = (document.getElementById('grid1_cell_0_0') || document.getElementById('mf_grid1_cell_0_0')).querySelector('input').getAttribute('checked')
	const checked2 = (document.getElementById('grid1_cell_1_0') || document.getElementById('mf_grid1_cell_1_0')).querySelector('input').getAttribute('checked')
	const checked3 = (document.getElementById('grid1_cell_2_0') || document.getElementById('mf_grid1_cell_2_0')).querySelector('input').getAttribute('checked')
	const checked4 = (document.getElementById('grid1_cell_3_0') || document.getElementById('mf_grid1_cell_3_0')).querySelector('input').getAttribute('checked')
	return checked1 == '' && checked2 == '' && checked3 == '' && checked4 == '';
};
